import { useSetState } from './selectors.js';
import { useHistogramInteractions } from '../useHistogramInteractions.js';
import { useHistogramXScale } from '../useHistogramXScale.js';

export const useSetResetOverlaysState = () => {
  const setState = useSetState();

  return () =>
    setState((prev) => ({
      ...prev,
      highlightedSeriesIds: prev.overlays.pinnedTooltip
        ? undefined
        : prev.highlightedSeriesIds,
      overlays: {
        visibleTooltip: false,
        pinnedTooltip: false,
      },
      zoom: {
        ...prev.zoom,
        keyboardFocusMode: undefined,
        activeKeyboardMode: undefined,
      },
    }));
};

export const useSetResetZoomState = () => {
  const setState = useSetState();
  const { onZoomChange } = useHistogramInteractions();
  const { initialXScale } = useHistogramXScale();

  return () => {
    const [start, end] = initialXScale.domain();
    onZoomChange && onZoomChange(start, end, 'reset');

    setState((prev) => ({
      ...prev,
      currentDomain: undefined,
      zoom: {
        zoomOutEnabled: false,
        zoomInEnabled: true,
        zoomMode: 'explore',
        keyboardFocusMode: undefined,
        activeKeyboardMode: undefined,
      },
    }));
  };
};
